# Q1 report update (idempotent: drops earlier entries whose evidence starts with 'Q1:')
import json
P='/output/report.json'; R=json.load(open(P)); res=[x for x in R['results'] if not x.get('evidence','').startswith('Q1:')]
A=[{"name":"line_windows","value":"core |v-VSYS|<350 km/s (VSYS=2780 radio-LSRK); w250/w500 windows change the ratios by <=3% (<=12% for faint clumps); per-pixel baseline from line-free channels (v<-600, 450-600)"},
   {"name":"beam_matching","value":"cubes convolved with the analytic Fourier Gaussian (flux rescaled by beam-area ratio, as in s26) to a circular 6.5\" or 10\" beam; HCN and HCO+ always at the same beam; ratios are of Jy km/s per beam (flux units); multiply by (nu_HCO+/nu_HCN)^2 = 1.0126 (J=2), 1.0126 (J=3), 1.0126 (J=4) for K km/s"},
   {"name":"flux_scale","value":"5% relative HCN-vs-HCO+ calibration (same OUS, adjacent windows) added in quadrature; filtering/recovery cancels in the ratio at N/S/Bridge (p0003) but not for faint clumps (factor 2)"},
   {"name":"positions","value":"N, S, Bridge, E1, E2, W, Sblue from regions.py (0.24-1\" moment maps); midpoint = N-S midpoint"}]
def add(q,t,v,u,unit,conf,ev): res.append(dict(quantity=q,target=t,value=v,uncertainty=u,unit=unit,assumptions=A,confidence=conf,evidence='Q1: '+ev))
